#include "sgsr3_fast_vk.h"
#include "log.h"
#include "SGSR3_V1f_spv.h" // generated by tools/gen_v1f_spv.py from

#include <algorithm>
#include <cstring>

static ID3D12Resource* FastBuf(ID3D12Device* dev, uint64_t bytes, D3D12_HEAP_TYPE type, D3D12_RESOURCE_STATES st)
{
    D3D12_HEAP_PROPERTIES heap{};
    heap.Type = type;
    D3D12_RESOURCE_DESC d{};
    d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    d.Width = bytes;
    d.Height = 1;
    d.DepthOrArraySize = 1;
    d.MipLevels = 1;
    d.SampleDesc.Count = 1;
    d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    ID3D12Resource* r = nullptr;
    if (FAILED(dev->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &d, st, nullptr, IID_PPV_ARGS(&r))))
        return nullptr;
    return r;
}

bool VkUpscalerV1f::MakeImage(Img& img, uint32_t w, uint32_t h, VkFormat fmt, VkImageUsageFlags usage)
{
    img.format = fmt;
    img.w = w;
    img.h = h;
    VkImageCreateInfo ci{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};
    ci.imageType = VK_IMAGE_TYPE_2D;
    ci.format = fmt;
    ci.extent = {w, h, 1};
    ci.mipLevels = 1;
    ci.arrayLayers = 1;
    ci.samples = VK_SAMPLE_COUNT_1_BIT;
    ci.tiling = VK_IMAGE_TILING_OPTIMAL;
    ci.usage = usage | VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT;
    ci.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
    if (vkCreateImage(_vk, &ci, nullptr, &img.image) != VK_SUCCESS)
        return false;
    VkMemoryRequirements req;
    vkGetImageMemoryRequirements(_vk, img.image, &req);
    VkPhysicalDeviceMemoryProperties mp;
    vkGetPhysicalDeviceMemoryProperties(_physical, &mp);
    uint32_t type = UINT32_MAX;
    for (uint32_t i = 0; i < mp.memoryTypeCount && type == UINT32_MAX; i++)
        if ((req.memoryTypeBits & (1u << i)) && (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT))
            type = i;
    VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
    ai.allocationSize = req.size;
    ai.memoryTypeIndex = type;
    if (type == UINT32_MAX || vkAllocateMemory(_vk, &ai, nullptr, &img.mem) != VK_SUCCESS ||
        vkBindImageMemory(_vk, img.image, img.mem, 0) != VK_SUCCESS)
        return false;
    VkImageViewCreateInfo vi{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};
    vi.image = img.image;
    vi.viewType = VK_IMAGE_VIEW_TYPE_2D;
    vi.format = fmt;
    vi.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
    return vkCreateImageView(_vk, &vi, nullptr, &img.view) == VK_SUCCESS;
}

bool VkUpscalerV1f::MakePass(Pass& p, const uint32_t* spv, size_t bytes,
                             const std::vector<std::pair<uint32_t, VkDescriptorType>>& bindings, bool fragment,
                             const VkFormat* rtFormats, uint32_t nRt)
{
    const VkShaderStageFlags stage = fragment ? VK_SHADER_STAGE_FRAGMENT_BIT : VK_SHADER_STAGE_COMPUTE_BIT;
    std::vector<VkDescriptorSetLayoutBinding> lb;
    for (const auto& b : bindings)
        lb.push_back({b.first, b.second, 1, stage, nullptr});
    VkDescriptorSetLayoutCreateInfo dci{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};
    dci.bindingCount = (uint32_t) lb.size();
    dci.pBindings = lb.data();
    if (vkCreateDescriptorSetLayout(_vk, &dci, nullptr, &p.dsl) != VK_SUCCESS)
        return false;
    VkPipelineLayoutCreateInfo li{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
    li.setLayoutCount = 1;
    li.pSetLayouts = &p.dsl;
    if (vkCreatePipelineLayout(_vk, &li, nullptr, &p.pl) != VK_SUCCESS)
        return false;
    VkShaderModuleCreateInfo mi{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};
    mi.codeSize = bytes;
    mi.pCode = spv;
    VkShaderModule mod = VK_NULL_HANDLE;
    if (vkCreateShaderModule(_vk, &mi, nullptr, &mod) != VK_SUCCESS)
        return false;
    VkResult vr;
    if (!fragment)
    {
        VkComputePipelineCreateInfo ci{VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO};
        ci.stage = {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};
        ci.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        ci.stage.module = mod;
        ci.stage.pName = "main";
        ci.layout = p.pl;
        vr = vkCreateComputePipelines(_vk, VK_NULL_HANDLE, 1, &ci, nullptr, &p.pipe);
    }
    else
    {
        VkPipelineShaderStageCreateInfo st[2] = {{VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO},
                                                 {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO}};
        st[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
        st[0].module = _vs;
        st[0].pName = "main";
        st[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
        st[1].module = mod;
        st[1].pName = "main";
        VkPipelineVertexInputStateCreateInfo vin{VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO};
        VkPipelineInputAssemblyStateCreateInfo ia{VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO};
        ia.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
        VkPipelineViewportStateCreateInfo vp{VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO};
        vp.viewportCount = vp.scissorCount = 1;
        VkPipelineRasterizationStateCreateInfo rs{VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO};
        rs.polygonMode = VK_POLYGON_MODE_FILL;
        rs.cullMode = VK_CULL_MODE_NONE;
        rs.lineWidth = 1.0f;
        VkPipelineMultisampleStateCreateInfo ms{VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO};
        ms.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
        std::vector<VkPipelineColorBlendAttachmentState> cba(nRt);
        for (auto& c : cba)
            c.colorWriteMask = 0xF;
        VkPipelineColorBlendStateCreateInfo cb{VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO};
        cb.attachmentCount = nRt;
        cb.pAttachments = cba.data();
        VkDynamicState dyn[2] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
        VkPipelineDynamicStateCreateInfo ds{VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO};
        ds.dynamicStateCount = 2;
        ds.pDynamicStates = dyn;
        VkPipelineRenderingCreateInfo ri{VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO};
        ri.colorAttachmentCount = nRt;
        ri.pColorAttachmentFormats = rtFormats;
        VkGraphicsPipelineCreateInfo gci{VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO};
        gci.pNext = &ri;
        gci.stageCount = 2;
        gci.pStages = st;
        gci.pVertexInputState = &vin;
        gci.pInputAssemblyState = &ia;
        gci.pViewportState = &vp;
        gci.pRasterizationState = &rs;
        gci.pMultisampleState = &ms;
        gci.pColorBlendState = &cb;
        gci.pDynamicState = &ds;
        gci.layout = p.pl;
        vr = vkCreateGraphicsPipelines(_vk, VK_NULL_HANDLE, 1, &gci, nullptr, &p.pipe);
    }
    vkDestroyShaderModule(_vk, mod, nullptr);
    if (vr != VK_SUCCESS)
        return false;
    for (uint32_t k = 0; k < Ring; k++)
    {
        VkDescriptorSetAllocateInfo ai{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};
        ai.descriptorPool = _pool;
        ai.descriptorSetCount = 1;
        ai.pSetLayouts = &p.dsl;
        if (vkAllocateDescriptorSets(_vk, &ai, &p.set[k]) != VK_SUCCESS)
            return false;
    }
    return true;
}

bool VkUpscalerV1f::Init(ID3D12Device* device, uint32_t rw, uint32_t rh, uint32_t dw, uint32_t dh, int bitSet,
                         Variant variant)
{
    _compact = variant != Variant::Rgba16;
    _lock = variant == Variant::Lock;
    _device = device;
    _rw = rw;
    _rh = rh;
    _dw = dw;
    _dh = dh;
    bitSet = std::clamp(bitSet, 0, 2);

    if (FAILED(device->QueryInterface(__uuidof(ID3D12DXVKInteropDevice1), (void**) &_interop)) || !_interop)
    {
        LOGI("v1f: no ID3D12DXVKInteropDevice1 (not vkd3d-proton, or too old)");
        return false;
    }
    if (FAILED(_interop->GetVulkanHandles(&_instance, &_physical, &_vk)) || _vk == VK_NULL_HANDLE)
        return false;
    GpuPatchInit(_vk);
    _beginRendering = (PFN_vkCmdBeginRendering) vkGetDeviceProcAddr(_vk, "vkCmdBeginRendering");
    _endRendering = (PFN_vkCmdEndRendering) vkGetDeviceProcAddr(_vk, "vkCmdEndRendering");
    if (!_beginRendering)
    {
        _beginRendering = (PFN_vkCmdBeginRendering) vkGetDeviceProcAddr(_vk, "vkCmdBeginRenderingKHR");
        _endRendering = (PFN_vkCmdEndRendering) vkGetDeviceProcAddr(_vk, "vkCmdEndRenderingKHR");
    }
    if (!_beginRendering || !_endRendering)
        return false;
    VkPhysicalDeviceProperties props{};
    vkGetPhysicalDeviceProperties(_physical, &props);
    _tsPeriodNs = props.limits.timestampPeriod;

    bool f16 = false, fragStores = false;
    const VkPhysicalDeviceFeatures2* feats = nullptr;
    if (SUCCEEDED(_interop->GetDeviceFeatures(&feats)) && feats)
    {
        fragStores = feats->features.fragmentStoresAndAtomics != VK_FALSE;
        for (auto* s = (const VkBaseInStructure*) feats->pNext; s; s = s->pNext)
        {
            if (s->sType == VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_2_FEATURES)
                f16 = ((const VkPhysicalDeviceVulkan12Features*) s)->shaderFloat16 != VK_FALSE;
            if (s->sType == VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SHADER_FLOAT16_INT8_FEATURES)
                f16 = f16 || ((const VkPhysicalDeviceShaderFloat16Int8Features*) s)->shaderFloat16 != VK_FALSE;
        }
    }
    if (!fragStores)
        _compute = true;
    if (_compute)
        _compact = _lock = false;
    static const char* setName[3] = {"v1a", "v1b", "v1c"};
    _info = std::string("v1f ") + setName[bitSet] + (_compute ? " compute" : " fragment") +
            (_compact ? ", compact" : ", RGBA16F") + (_lock ? ", locks" : "") + ", shaderFloat16 " + (f16 ? "on" : "OFF");
    LOGI("v1f: %s", _info.c_str());
    if (!f16)
        return false;

    VkDescriptorPoolSize ps[3] = {{VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 4 * Ring},
                                  {VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 16 * Ring},
                                  {VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 4 * Ring}};
    VkDescriptorPoolCreateInfo dpi{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};
    dpi.maxSets = 4 * Ring;
    dpi.poolSizeCount = 3;
    dpi.pPoolSizes = ps;
    if (vkCreateDescriptorPool(_vk, &dpi, nullptr, &_pool) != VK_SUCCESS)
        return false;
    VkSamplerCreateInfo si{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};
    si.addressModeU = si.addressModeV = si.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    si.maxLod = 0.0f;
    si.magFilter = si.minFilter = VK_FILTER_NEAREST;
    si.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
    if (vkCreateSampler(_vk, &si, nullptr, &_point) != VK_SUCCESS)
        return false;
    si.magFilter = si.minFilter = VK_FILTER_LINEAR;
    if (vkCreateSampler(_vk, &si, nullptr, &_linear) != VK_SUCCESS)
        return false;
    VkShaderModuleCreateInfo mi{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};
    mi.codeSize = sizeof(v1f_spv_fullscreen_vert);
    mi.pCode = v1f_spv_fullscreen_vert;
    if (vkCreateShaderModule(_vk, &mi, nullptr, &_vs) != VK_SUCCESS)
        return false;
    VkQueryPoolCreateInfo qi{VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
    qi.queryType = VK_QUERY_TYPE_TIMESTAMP;
    qi.queryCount = TsPerFrame * Ring;
    if (vkCreateQueryPool(_vk, &qi, nullptr, &_queries) != VK_SUCCESS)
        _queries = VK_NULL_HANDLE;

    _ubo = FastBuf(device, 256 * Ring, D3D12_HEAP_TYPE_UPLOAD, D3D12_RESOURCE_STATE_GENERIC_READ);
    _flush[0] = FastBuf(device, 256, D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_COPY_SOURCE);
    _flush[1] = FastBuf(device, 256, D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_COPY_DEST);
    if (!_ubo || !_flush[0] || !_flush[1])
        return false;
    D3D12_RANGE noRead{0, 0};
    if (FAILED(_ubo->Map(0, &noRead, (void**) &_uboMapped)))
        return false;
    UINT64 handle = 0;
    if (FAILED(_interop->GetVulkanResourceInfo1(_ubo, &handle, &_uboOffset, nullptr)) || !handle)
        return false;
    _uboBuffer = (VkBuffer) handle;

    const VkImageUsageFlags RTU = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
    const VkFormat F16 = VK_FORMAT_R16G16B16A16_SFLOAT;
    const VkFormat F10 = VK_FORMAT_A2B10G10R10_UNORM_PACK32;
    if (!MakeImage(_mdr, rw, rh, F16, RTU) || !MakeImage(_work, rw, rh, _compact ? F10 : F16, RTU))
        return false;
    for (int k = 0; k < 2; k++)
    {
        if (!MakeImage(_hist[k], dw, dh, _compact ? F10 : F16, _compute ? VK_IMAGE_USAGE_STORAGE_BIT : RTU))
            return false;
        if (_compact && !MakeImage(_histN[k], dw, dh, _lock ? VK_FORMAT_R16G16_SFLOAT : VK_FORMAT_R16_SFLOAT, RTU))
            return false;
    }

    using B = std::pair<uint32_t, VkDescriptorType>;
    const VkDescriptorType U = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, S = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER,
                           I = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    const VkFormat convRt[2] = {F16, _work.format};
    if (!MakePass(_convert, _lock ? v1f_spv_convert_lock_frag : v1f_spv_convert_frag,
                  _lock ? sizeof(v1f_spv_convert_lock_frag) : sizeof(v1f_spv_convert_frag),
                  {B(0, U), B(1, S), B(2, S), B(3, S), B(4, S)}, true, convRt, 2))
        return false;
    const V1fSpv& up = _compute ? v1f_upscale_comp[bitSet]
                       : _compact ? (_lock ? v1f_upscale_fragcl[bitSet] : v1f_upscale_fragc[bitSet])
                                  : v1f_upscale_frag[bitSet];
    std::vector<B> ub = {B(0, U), B(1, S), B(2, S), B(3, S), B(4, S), B(5, S), B(8, I)};
    if (_compute)
        ub.push_back(B(7, I));
    if (_compact)
        ub.push_back(B(6, S));
    const VkFormat upRt[2] = {_hist[0].format, _compact ? _histN[0].format : VK_FORMAT_R16_SFLOAT};
    if (!MakePass(_upscale, up.spv, up.bytes, ub, !_compute, upRt, _compact ? 2 : 1))
        return false;
    _ready = true;
    return true;
}

VkImageView VkUpscalerV1f::GameView(ID3D12Resource* res, VkFormat& fmt, bool depth)
{
    UINT64 handle = 0, offset = 0;
    fmt = VK_FORMAT_UNDEFINED;
    if (!res || FAILED(_interop->GetVulkanResourceInfo1(res, &handle, &offset, &fmt)) || !handle)
        return VK_NULL_HANDLE;
    const auto key = std::make_tuple((uint64_t) handle, (int) fmt, depth ? 1 : 0);
    auto it = _gameViews.find(key);
    if (it != _gameViews.end())
        return it->second;
    VkImageViewCreateInfo vi{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};
    vi.image = (VkImage) handle;
    vi.viewType = VK_IMAGE_VIEW_TYPE_2D;
    vi.format = fmt;
    //: the depth input may be a colour-format copy (RE4 hands FSR 2 an R32_FLOAT copy of its
    // depth): the depth aspect only for real depth formats
    depth = depth && (fmt == VK_FORMAT_D32_SFLOAT || fmt == VK_FORMAT_D32_SFLOAT_S8_UINT ||
                      fmt == VK_FORMAT_D24_UNORM_S8_UINT || fmt == VK_FORMAT_X8_D24_UNORM_PACK32 ||
                      fmt == VK_FORMAT_D16_UNORM || fmt == VK_FORMAT_D16_UNORM_S8_UINT);
    vi.subresourceRange = {depth ? (VkImageAspectFlags) VK_IMAGE_ASPECT_DEPTH_BIT
                                 : (VkImageAspectFlags) VK_IMAGE_ASPECT_COLOR_BIT,
                           0, 1, 0, 1};
    VkImageView v = VK_NULL_HANDLE;
    if (vkCreateImageView(_vk, &vi, nullptr, &v) != VK_SUCCESS)
        return VK_NULL_HANDLE;
    _gameViews[key] = v;
    _retiring.push_back({_frame, v});
    return v;
}

bool VkUpscalerV1f::Evaluate(ID3D12GraphicsCommandList* cl, const Input& color, const Input& depth, const Input& mv,
                             const Input& reactive, const Input& tc, const Input& output, const void* constants,
                             size_t bytes, bool reset)
{
    if (!_ready || bytes > 256)
        return false;
    //: views of the game's images live for one call (a freed image's VkImage handle may come back for a
    // new image after a level load); destroyed 2 x Ring calls later, when their command buffers are done
    _gameViews.clear();
    for (size_t i = 0; i < _retiring.size();)
        if (_retiring[i].first + 2 * Ring <= _frame)
        {
            vkDestroyImageView(_vk, _retiring[i].second, nullptr);
            _retiring.erase(_retiring.begin() + i);
        }
        else
            i++;
    const uint32_t slot = _frame % Ring;
    const int k = _parity;

    VkFormat fc, fd, fm, fo, fr, ft;
    VkImageView vColor = GameView(color.res, fc, false);
    VkImageView vDepth = depth.res ? GameView(depth.res, fd, true) : VK_NULL_HANDLE;
    VkImageView vMv = GameView(mv.res, fm, false);
    VkImageView vOut = GameView(output.res, fo, false);
    VkImageView vReact = reactive.res ? GameView(reactive.res, fr, false) : VK_NULL_HANDLE;
    VkImageView vTc = tc.res ? GameView(tc.res, ft, false) : VK_NULL_HANDLE;
    if (vColor == VK_NULL_HANDLE || vMv == VK_NULL_HANDLE || vOut == VK_NULL_HANDLE)
        return false;
    VkImageLayout lColor, lDepth = VK_IMAGE_LAYOUT_GENERAL, lMv, lOut, lReact = VK_IMAGE_LAYOUT_GENERAL,
                         lTc = VK_IMAGE_LAYOUT_GENERAL;
    _interop->GetVulkanImageLayout(color.res, color.state, &lColor);
    if (depth.res)
        _interop->GetVulkanImageLayout(depth.res, depth.state, &lDepth);
    _interop->GetVulkanImageLayout(mv.res, mv.state, &lMv);
    _interop->GetVulkanImageLayout(output.res, output.state, &lOut);
    if (reactive.res)
        _interop->GetVulkanImageLayout(reactive.res, reactive.state, &lReact);
    if (tc.res)
        _interop->GetVulkanImageLayout(tc.res, tc.state, &lTc);
    const VkImageLayout OWN = VK_IMAGE_LAYOUT_GENERAL;
    if (vDepth == VK_NULL_HANDLE) { vDepth = _hist[k].view; lDepth = OWN; }
    if (vReact == VK_NULL_HANDLE) { vReact = _hist[k].view; lReact = OWN; }
    if (vTc == VK_NULL_HANDLE) { vTc = _hist[k].view; lTc = OWN; }

    memcpy(_uboMapped + slot * 256, constants, bytes);
    if (!_imagesInitialised || reset)
    {
        const float one = 1.0f;
        memcpy(_uboMapped + slot * 256 + 80, &one, 4); // reset field offset in SGSR3Constants
    }
    const VkDescriptorBufferInfo ubi{_uboBuffer, _uboOffset + slot * 256, 256};

    std::vector<VkWriteDescriptorSet> wr;
    std::vector<VkDescriptorImageInfo> ii;
    ii.reserve(32);
    auto put = [&](VkDescriptorSet set, uint32_t binding, VkDescriptorType type, VkImageView v, VkImageLayout l,
                   VkSampler s) {
        ii.push_back({s, v, l});
        VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
        w.dstSet = set;
        w.dstBinding = binding;
        w.descriptorCount = 1;
        w.descriptorType = type;
        w.pImageInfo = &ii.back();
        wr.push_back(w);
    };
    auto putUbo = [&](VkDescriptorSet set) {
        VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
        w.dstSet = set;
        w.dstBinding = 0;
        w.descriptorCount = 1;
        w.descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
        w.pBufferInfo = &ubi;
        wr.push_back(w);
    };
    const VkDescriptorType S = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, I = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    VkDescriptorSet cs = _convert.set[slot], us = _upscale.set[slot];
    putUbo(cs);
    put(cs, 1, S, vDepth, lDepth, _point);
    put(cs, 2, S, vMv, lMv, _point);
    put(cs, 3, S, vReact, lReact, _point);
    put(cs, 4, S, vColor, lColor, _point);
    putUbo(us);
    put(us, 1, S, _work.view, OWN, _point);
    put(us, 2, S, _mdr.view, OWN, _linear);
    put(us, 3, S, _hist[k].view, OWN, _linear);
    put(us, 4, S, vTc, lTc, _linear);
    put(us, 5, S, _work.view, OWN, _linear);
    put(us, 8, I, vOut, lOut, VK_NULL_HANDLE);
    if (_compact)
        put(us, 6, S, _histN[k].view, OWN, _linear);
    if (_compute)
        put(us, 7, I, _hist[1 - k].view, OWN, VK_NULL_HANDLE);
    vkUpdateDescriptorSets(_vk, (uint32_t) wr.size(), wr.data(), 0, nullptr);

    cl->CopyBufferRegion(_flush[1], 0, _flush[0], 0, 4); // flush vkd3d's batched D3D12 barriers
    VkCommandBuffer cb = VK_NULL_HANDLE;
    if (FAILED(_interop->BeginVkCommandBufferInterop(cl, &cb)) || cb == VK_NULL_HANDLE)
        return false;
    VkMemoryBarrier mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER};
    mb.srcAccessMask = VK_ACCESS_MEMORY_WRITE_BIT;
    mb.dstAccessMask = VK_ACCESS_MEMORY_READ_BIT | VK_ACCESS_MEMORY_WRITE_BIT;
    vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, 0, 1, &mb, 0,
                         nullptr, 0, nullptr);
    RecordGpuPatches(cb, _patches, _uboBuffer, _uboOffset + (uint64_t) slot * 256); // per-frame fields from the game's GPU cbuffer
    if (!_imagesInitialised)
    {
        std::vector<VkImageMemoryBarrier> ib;
        for (Img* im : {&_mdr, &_work, &_hist[0], &_hist[1], &_histN[0], &_histN[1]})
        {
            if (im->image == VK_NULL_HANDLE)
                continue;
            VkImageMemoryBarrier b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};
            b.dstAccessMask =
                VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT | VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
            b.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED;
            b.newLayout = VK_IMAGE_LAYOUT_GENERAL;
            b.srcQueueFamilyIndex = b.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
            b.image = im->image;
            b.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
            ib.push_back(b);
        }
        vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, 0, 0, nullptr, 0,
                             nullptr, (uint32_t) ib.size(), ib.data());
        _imagesInitialised = true;
    }
    const uint32_t q0 = slot * TsPerFrame;
    if (_queries != VK_NULL_HANDLE)
    {
        vkCmdResetQueryPool(cb, _queries, q0, TsPerFrame);
        vkCmdWriteTimestamp(cb, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, _queries, q0);
    }

    auto draw = [&](Pass& p, Img* const* rts, uint32_t nRt, uint32_t w, uint32_t h) {
        VkRenderingAttachmentInfo att[2] = {{VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO},
                                            {VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO}};
        for (uint32_t i = 0; i < nRt; i++)
        {
            att[i].imageView = rts[i]->view;
            att[i].imageLayout = VK_IMAGE_LAYOUT_GENERAL;
            att[i].loadOp = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
            att[i].storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        }
        VkRenderingInfo ri{VK_STRUCTURE_TYPE_RENDERING_INFO};
        ri.renderArea = {{0, 0}, {w, h}};
        ri.layerCount = 1;
        ri.colorAttachmentCount = nRt;
        ri.pColorAttachments = att;
        _beginRendering(cb, &ri);
        VkViewport v{0, 0, (float) w, (float) h, 0, 1};
        VkRect2D sc{{0, 0}, {w, h}};
        vkCmdSetViewport(cb, 0, 1, &v);
        vkCmdSetScissor(cb, 0, 1, &sc);
        vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, p.pipe);
        vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, p.pl, 0, 1, &p.set[slot], 0, nullptr);
        vkCmdDraw(cb, 3, 1, 0, 0);
        _endRendering(cb);
    };

    Img* convRts[2] = {&_mdr, &_work};
    draw(_convert, convRts, 2, _rw, _rh);
    VkMemoryBarrier rb{VK_STRUCTURE_TYPE_MEMORY_BARRIER};
    rb.srcAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
    rb.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
    vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,
                         VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &rb, 0,
                         nullptr, 0, nullptr);
    if (_queries != VK_NULL_HANDLE)
        vkCmdWriteTimestamp(cb, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, _queries, q0 + 1);
    if (_compute)
    {
        vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_COMPUTE, _upscale.pipe);
        vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_COMPUTE, _upscale.pl, 0, 1, &_upscale.set[slot], 0, nullptr);
        vkCmdDispatch(cb, (_dw + V1fWgX - 1) / V1fWgX, (_dh + V1fWgY - 1) / V1fWgY, 1);
    }
    else
    {
        Img* upRts[2] = {&_hist[1 - k], &_histN[1 - k]};
        draw(_upscale, upRts, _compact ? 2 : 1, _dw, _dh);
    }
    if (_queries != VK_NULL_HANDLE)
        vkCmdWriteTimestamp(cb, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, _queries, q0 + 2);
    vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, 0, 1, &mb, 0,
                         nullptr, 0, nullptr);
    _interop->EndVkCommandBufferInterop(cl);
    _parity ^= 1;
    _frame++;
    return true;
}

bool VkUpscalerV1f::LastTiming(double out[2])
{
    if (_queries == VK_NULL_HANDLE || _frame < Ring)
        return false;
    const uint32_t slot = (_frame + 1) % Ring;
    uint64_t ts[TsPerFrame]{};
    if (vkGetQueryPoolResults(_vk, _queries, slot * TsPerFrame, TsPerFrame, sizeof(ts), ts, sizeof(uint64_t),
                              VK_QUERY_RESULT_64_BIT) != VK_SUCCESS)
        return false;
    for (int i = 0; i < 2; i++)
        out[i] = ts[i + 1] >= ts[i] ? (double) (ts[i + 1] - ts[i]) * _tsPeriodNs * 1e-6 : 0.0;
    return true;
}

void VkUpscalerV1f::Release()
{
    if (_vk != VK_NULL_HANDLE)
    {
        for (Pass* p : {&_convert, &_upscale})
        {
            if (p->pipe) vkDestroyPipeline(_vk, p->pipe, nullptr);
            if (p->pl) vkDestroyPipelineLayout(_vk, p->pl, nullptr);
            if (p->dsl) vkDestroyDescriptorSetLayout(_vk, p->dsl, nullptr);
            *p = Pass{};
        }
        for (Img* i : {&_mdr, &_work, &_hist[0], &_hist[1], &_histN[0], &_histN[1]})
        {
            if (i->view) vkDestroyImageView(_vk, i->view, nullptr);
            if (i->image) vkDestroyImage(_vk, i->image, nullptr);
            if (i->mem) vkFreeMemory(_vk, i->mem, nullptr);
            *i = Img{};
        }
        for (auto& v : _retiring)
            vkDestroyImageView(_vk, v.second, nullptr);
        _retiring.clear();
        _gameViews.clear();
        if (_pool) vkDestroyDescriptorPool(_vk, _pool, nullptr);
        if (_point) vkDestroySampler(_vk, _point, nullptr);
        if (_linear) vkDestroySampler(_vk, _linear, nullptr);
        if (_vs) vkDestroyShaderModule(_vk, _vs, nullptr);
        if (_queries) vkDestroyQueryPool(_vk, _queries, nullptr);
        _pool = VK_NULL_HANDLE;
        _point = _linear = VK_NULL_HANDLE;
        _vs = VK_NULL_HANDLE;
        _queries = VK_NULL_HANDLE;
    }
    if (_ubo) _ubo->Release();
    _ubo = nullptr;
    for (auto*& f : _flush)
        if (f) { f->Release(); f = nullptr; }
    if (_interop) _interop->Release();
    _interop = nullptr;
    _imagesInitialised = false;
    _ready = false;
    _frame = 0;
    _parity = 0;
}
